import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import SiteDocument from "./SiteDocument.js";

describe("SiteDocument SSR", () => {
  it("server-renders the whole document around the application", () => {
    const html = renderToString(
      <SiteDocument head={<meta charSet="utf-8" />} lang="en" theme="light">
        <main>Stations</main>
      </SiteDocument>,
    );
    expect(html).toBe(
      '<html lang="en" class="ds site-document app comfortable light">' +
        '<head><meta charSet="utf-8"/></head>' +
        '<body><div id="root"><main>Stations</main></div></body></html>',
    );
  });
});
